SNULL(MAX(Es_Sign2),'')) > 6 THEN SUBSTRING(MAX(Es_Sign2),9,10) ELSE ISNULL(MAX(Es_Sign2),'') END,MAX(Es_Date),3) END, cc_SignTt3 = CASE WHEN ISNULL(MAX(Es_Sign3),'') = '' THEN '' ELSE CASE WHEN ISNULL(MAX(Es_SignDt3),'') = '' THEN '□ ' ELSE '▣ ' END + dbo.GetSaJikGub(CASE WHEN LEN(ISNULL(MAX(Es_Sign3),'')) > 6 THEN SUBSTRING(MAX(Es_Sign3),9,10) ELSE ISNULL(MAX(Es_Sign3),'') END,MAX(Es_Date),3) END, cc_SignTt4 = CASE WHEN ISNULL(MAX(Es_Sign4),'') = '' THEN '' ELSE CASE WHEN ISNULL(MAX(Es_SignDt4),'') = '' THEN '□ ' ELSE '▣ ' END + dbo.GetSaJikGub(CASE WHEN LEN(ISNULL(MAX(Es_Sign4),'')) > 6 THEN SUBSTRING(MAX(Es_Sign4),9,10) ELSE ISNULL(MAX(Es_Sign4),'') END,MAX(Es_Date),3) END, cc_SignTt5 = CASE WHEN ISNULL(MAX(Es_Sign5),'') = '' THEN '' ELSE CASE WHEN ISNULL(MAX(Es_SignDt5),'') = '' THEN '□ ' ELSE '▣ ' END + dbo.GetSaJikGub(CASE WHEN LEN(ISNULL(MAX(Es_Sign5),'')) > 6 THEN SUBSTRING(MAX(Es_Sign5),9,10) ELSE ISNULL(MAX(Es_Sign5),'') END,MAX(Es_Date),3) END, cc_SignTt6 = CASE WHEN ISNULL(MAX(Es_Sign6),'') = '' THEN '' ELSE CASE WHEN ISNULL(MAX(Es_SignDt6),'') = '' THEN '□ ' ELSE '▣ ' END + dbo.GetSaJikGub(CASE WHEN LEN(ISNULL(MAX(Es_Sign6),'')) > 6 THEN SUBSTRING(MAX(Es_Sign6),9,10) ELSE ISNULL(MAX(Es_Sign6),'') END,MAX(Es_Date),3) END, cc_SignTt7 = CASE WHEN ISNULL(MAX(Es_Sign7),'') = '' THEN '' ELSE CASE WHEN ISNULL(MAX(Es_SignDt7),'') = '' THEN '□ ' ELSE '▣ ' END + dbo.GetSaJikGub(CASE WHEN LEN(ISNULL(MAX(Es_Sign7),'')) > 6 THEN SUBSTRING(MAX(Es_Sign7),9,10) ELSE ISNULL(MAX(Es_Sign7),'') END,MAX(Es_Date),3) END, cc_SignTt8 = CASE WHEN ISNULL(MAX(Es_Sign8),'') = '' THEN '' ELSE CASE WHEN ISNULL(MAX(Es_SignDt8),'') = '' THEN '□ ' ELSE '▣ ' END + dbo.GetSaJikGub(CASE WHEN LEN(ISNULL(MAX(Es_Sign8),'')) > 6 THEN SUBSTRING(MAX(Es_Sign8),9,10) ELSE ISNULL(MAX(Es_Sign8),'') END,MAX(Es_Date),3) END, chk = 0 FROM O_OSOrderList LEFT JOIN I_ElecSign ON Es_Code = Or_ElecUK AND Es_Flag = 'OR' LEFT JOIN P_InSaCode ON Ic_Code = CASE WHEN LEN(Es_Sign1) > 8 THEN SUBSTRING(Es_Sign1, 9, 10) ELSE Es_Sign1 END LEFT JOIN P_InsaDetail ON Id_code = Ic_code AND Id_DtFlag = 4 AND Id_Saflag = Ic_Saflag AND Id_Date1 = ( SELECT MAX(Id_Date1) FROM P_InsaDetail WHERE Id_code = Ic_code AND Id_DtFlag = 4 AND Id_Saflag = Ic_Saflag AND Id_Date1 <= Es_Date ) WHERE Or_ComCD = '001' AND Or_Date BETWEEN #{searchFromDate} AND #{searchToDate} AND Or_Flag < '90'
AND Or_Buser = #{searchBuserCd}
GROUP BY Or_ComCD, Or_Date, Or_Number, Or_Flag, Or_Buser ORDER BY Or_Date DESC
